package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ArtLiveExamPracticalCritBank2 {
    private const val T = "දෘෂ්ටිකෝණ, මානව ව්‍යුහය, ප්‍රායෝගික මාධ්‍ය හා විචාරය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("පෙරබිම, මැදිබිම සහ පසුබිම (Foreground, Middleground, Background) නිවැරදිව සංවිධානය කිරීමෙන් භූ දර්ශන සිතුවමකට ලැබෙන්නේ කුමක්ද?", "ත්‍රිමාණ ගැඹුර හා අවකාශීය හැඟීම", "සම්පූර්ණ පැතලි ද්විමාන ස්වභාවය", "සමස්ත වර්ණ ප්‍රතිවිරෝධතාව අඩු වීම", "ද්විලක්ෂ්‍ය සමමිතික රටා නිර්මාණය", "පෙරබිමේ වස්තු විශාලව හා පැහැදිලිවද පසුබිමේ වස්තු කුඩාවට හා මෘදුවද ඇඳීමෙන් ගැඹුර මැවේ."),
        q("දෘෂ්ටිකෝණ චිත්‍රයේදී 'පක්ෂි ඇසේ දසුන' (Bird's-Eye View) යනු නරඹන්නා කුමන ස්ථානයක සිට බැලීමද?", "ඉහළ අහසේ සිට පහළ පොළොව දෙස බැලීම", "පොළොව මට්ටමේ සිට ඉහළ අහස දෙස බැලීම", "නරඹන්නාගේ සාමාන්‍ය ඇස් මට්ටමෙන් ඉදිරිය බැලීම", "භූමියේ සිට තිරස් බිත්තියක කෙළවර දෙස බැලීම", "ක්ෂිතිජ රේඛාව කඩදාසියේ ඉතා ඉහළින් ඇඳ පහළ භූමියේ වස්තු පෙන්වීම මෙම දසුනේ ලක්ෂණයකි."),
        q("දෘෂ්ටිකෝණ චිත්‍රයේදී 'පණුවාගේ ඇසේ දසුන' (Worm's-Eye View) යොදාගෙන ගොඩනැගිල්ලක් හෝ ගසක් ඇන්ද විට ඇති වන බලපෑම කුමක්ද?", "වස්තුව ඉතා විශාල, උස් හා බලසම්පන්න ලෙස පෙනීම", "වස්තුව කුඩා සෙල්ලම් බඩුවක් මෙන් පෙනීම", "කිසිදු ගැඹුරක් නොපෙනීම", "වහලය පමණක් පෙනීම", "ක්ෂිතිජ රේඛාව පහළින් තබා පහළ සිට ඉහළට බලන කෝණයෙන් ගොඩනැගිලි දැවැන්තව පෙන්වයි."),
        q("වායුගෝලීය දෘෂ්ටිකෝණයේදී (Atmospheric Perspective) දුර ඈත පිහිටි කඳු වැටි සහ ගස් ඉදිරිපසට වඩා වෙනස් වන්නේ කෙසේද?", "වර්ණ දීප්තිය අඩු වී, සිසිල් නිල්-අළු පැහැයට හැරී මායිම් බොඳ වී පෙනීම", "ඉතා තද කළු හා රතු පැහැයෙන් පෙනීම", "විශාලව හා තියුණු රේඛාවලින් පෙනීම", "සම්පූර්ණයෙන් කොටු හැඩයට හැරීම", "වායුගෝලයේ ඇති දූවිලි හා ජල වාෂ්ප නිසා ඈත වස්තූන්ගේ ප්‍රතිවිරෝධතාව හා විස්තර අඩු වේ."),
        q("මිනිස් සිරුරේ 'මැණික් කටුව සහ උරහිස' අතර ඇති වැලමිට පිහිටන්නේ සිරුරේ කුමන මට්ටමට ආසන්නවද?", "ඉණ හෙවත් නාභියට ආසන්න මට්ටමට", "දණහිස මට්ටමට", "නිකට මට්ටමට", "වළලුකර මට්ටමට", "අත කෙළින් පහළට දැමූ විට වැලමිට ඉණ මට්ටමේද මැණික් කටුව ඉඟට පහළින්ද කලව මැද ඇඟිලි තුඩුද පිහිටයි."),
        q("ළදරුවෙකුගේ හෝ කුඩා දරුවෙකුගේ ශරීර සමානුපාතය වැඩිහිටියෙකුගේ (හිස් 8) සමානුපාතයෙන් වෙනස් වන්නේ කෙසේද?", "දරුවෙකුගේ මුළු උස හිස් 4-5ක් පමණ වේ", "දරුවෙකුගේ මුළු උස හිස් 10-12ක් පමණ වේ", "දරුවෙකුගේ හිස සිරුරට වඩා ඉතා කුඩාය", "වැඩිහිටියෙකු හා සමාන අනුපාතයක්ම පවතී", "වයස අඩු වන විට සිරුරේ උසට සාපේක්ෂව හිසේ අනුපාතය වැඩි බව මානව චිත්‍ර ඇඳීමේදී සැලකිලිමත් විය යුතුය."),
        q("මිනිස් මුහුණක් 'පැතිකඩින්' (Profile View) ඇඳීමේදී නළල, නාසය, තොල් සහ නිකට පිහිටන ආකාරය නිවැරදිව ගොඩනගන්නේ කෙසේද?", "වෘත්තයක හා තිරස් මාර්ගෝපදේශ රේඛා මගින්", "සමපාද ත්‍රිකෝණයක් මැද සියලු අංග ඇඳීමෙන්", "කන් නළල මැද පිහිටුවා නාසය ඇඳීමෙන්", "ඇස ඉදිරිපස දසුන මෙන් රවුමට පළල්ව ඇඳීමෙන්", "පැතිකඩ මුහුණේ ඇස ත්‍රිකෝණාකාර හැඩයකින් පෙනෙන අතර තොල් හා නාසය පිටතට නෙරා සිටී."),
        q("චිත්‍ර පන්තියක 'ස්ටිල් ලයිෆ්' (Still Life / නිශ්චල ද්‍රව්‍ය සංයෝජනය) ඇඳීමෙන් සිසුන් ප්‍රගුණ කරන ප්‍රධාන කුසලතා මොනවාද?", "සමානුපාත, ඉලිප්ස, තානය හා වයනය නිරීක්ෂණය", "රෙදි මත උණු ඉටි හා ඩයි වර්ණ මිශ්‍ර කිරීම", "බතික් හා ලිනෝ කැපුම් අච්චු සූදානම් කිරීම", "පෞරාණික සිතුවම් රසායනිකව සංරක්ෂණය කිරීම", "වීදුරු, මැටි කළ, පලතුරු හා රෙදිවල පැහැදිලි හැඩ හා සෙවණැලි අධ්‍යයනය චිත්‍ර පදනමයි."),
        q("වෘත්තාකාර කටක් ඇති කළයක් හෝ කෝප්පයක් ඇස් මට්ටමට පහළින් ඇති විට එහි කට පෙනෙන හැඩය කුමක්ද?", "සමමිතික අණ්ඩාකාර ඉලිප්සයක් (Ellipse)", "කෙළවර උල් වූ අඩසඳක හැඩයක්", "සෘජුකෝණාස්‍රාකාර තිරස් තීරුවක්", "සමපාද ත්‍රිකෝණාකාර සමෝච්ඡයක්", "කෝප්පයේ කට ඇස් මට්ටමෙන් පහළට යන තරමට ඉලිප්සයේ පළල වැඩි වන අතර ඇස් මට්ටමේදී සෘජු රේඛාවක් වේ."),
        q("ජල සායම් සිතුවම් ඇඳීම සඳහා වඩාත් සුදුසු කඩදාසි වර්ගය හා ග්‍රෑම් බර කුමක්ද?", "ඝන 300 gsm පමණ කපු ජල සායම් කඩදාසි", "සිනිඳු තුනී ලිපි කවර හා පිටපත් කඩදාසි", "වතුර උරා නොගන්නා දිලිසෙන පොලිතින් පත්‍ර", "ලැමිනේට් කළ පැතලි කාඩ්බෝඩ් පුවරු", "තුනී කඩදාසි ජලය ගෑ විගස රැලි ගැසී ඉරෙන බැවින් ඝන වයනයක් ඇති කඩදාසි අවශ්‍ය වේ."),
        q("ජල සායම්වල 'ඩ්‍රයි බ්‍රෂ්' (Dry Brush) ශිල්පය යොදා ගන්නේ කුමන වයනයක් මැවීමටද?", "දැව පොතු, රළු ගල් හා තණකොළ වැනි වයනය", "ඉතා සිනිඳු විනිවිද පෙනෙන වීදුරු මතුපිටක්", "ඒකාකාරී පැතලි ග්‍රැෆික් පෝස්ටර් පසුබිමක්", "මෘදුව මුසු වූ සැහැල්ලු සවස් වලාකුළු පෙළක්", "ඉතා අඩු තෙතමනයක් ඇති පින්සලක් රළු කඩදාසි මත ගෑමෙන් කැඩුණු තීන්ත සලකුණු මතු වේ."),
        q("ජල සායම් චිත්‍රයක කුඩා සුදු ආලෝක තිත් හෝ රේඛා පසුව තීන්ත ගෑමේදී ආරක්ෂා කර තබා ගැනීමට ගාන ද්‍රව්‍යය කුමක්ද?", "මාස්කිං දියරය (Masking Fluid) හෝ ඉටි", "තද කළු තෙල් තීන්ත හෝ තාර ද්‍රාවණය", "හණ තෙල් හා ටර්පන්ටයින් මිශ්‍රණය", "සිමෙන්ති කුඩු හා සියුම් වැලි මිශ්‍රණය", "සුදු කොටස් මත මාස්කිං දියරය ගා වියළුණු පසු උඩින් තීන්ත ගා පසුව රබර් මෙන් ඉවත් කරයි."),
        q("ජල සායම් සිතුවමක් මත තෙත් තීන්ත ඇති විට 'සාමාන්‍ය ලුණු කැට' (Salt) ඉසීමෙන් ලැබෙන විශේෂිත ප්‍රයෝගය කුමක්ද?", "ජලය උරා ගැනීමෙන් ස්වභාවික තිත් රටා මැවීම", "මුළු කඩදාසියම තද කළු පැහැයට හැරීම", "තීන්ත ස්තරය ඉක්මනින් ඉරිතළා ගැලවී යාම", "සිතුවමේ සියලු රේඛා කෙළින් හා සෘජු වීම", "මුහුදු පෙණ, ගල් පෘෂ්ඨ හා තරු වැනි කලාත්මක වයන සෑදීමට ලුණු භාවිත කළ හැකිය."),
        q("පින්සල් වර්ගීකරණයේදී 'රවුම් පින්සල්' (Round Brush) සහ 'පැතලි පින්සල්' (Flat Brush) භාවිතයේ ප්‍රධාන වෙනස කුමක්ද?", "රවුම් පින්සල විස්තරටත් පැතලි පින්සල තලටත් යොදයි", "පැතලි පින්සල සියුම් තිත් තැබීමට පමණක් ගනී", "රවුම් පින්සල පුළුල් බිත්ති වැසීමට පමණක් ගනී", "හැඩය වෙනස් වුවත් භාවිතයේ කිසිදු වෙනසක් නැත", "කෙඳි ස්වභාවය අනුව විවිධ හැඩ හා පහරවල් මැවීමට විශේෂිත පින්සල් හැඩතල (Filbert, Fan, Liner) තෝරා ගනී."),
        q("භාවිතයෙන් පසු තීන්ත පින්සල් දිගු කල් ආරක්ෂා කර ගැනීමට කළ යුතු නිවැරදි නඩත්තු ක්‍රමය කුමක්ද?", "හොඳින් සෝදා හැඩය සකසා තිරස්ව වේළීමට තැබීම", "ජල බඳුනේ පතුලේ කෙඳි යටට සිටින සේ තැබීම", "වර්ණ තීන්ත නොසෝදා වියළී සවි වීමට හැරීම", "තෙත පින්සල් තද උණුසුම් අව්වේ බිම තැබීම", "වතුර බඳුනේ පතුලට තද වී තිබුණහොත් පින්සල් කෙඳි ස්ථිරවම ඇද වී නැවෙයි."),
        q("තෙල් සායම් හෝ ඇක්‍රිලික් චිත්‍ර ඇඳීම සඳහා 'කැන්වස්' (Canvas) රෙද්ද සකස් කිරීමේදී මුලින්ම ආලේප කරන සුදු ආරක්ෂිත තට්ටුව කුමක්ද?", "ජෙසෝ (Gesso / ප්‍රයිමර්)", "වලිත්ති", "ටර්පන්ටයින්", "මී ඉටි", "අමු රෙද්ද තීන්ත උරාගෙන දිරා යාම වැළැක්වීමටත් සිනිඳු පසුබිමක් සෑදීමටත් ජෙසෝ ගානු ලැබේ."),
        q("ග්‍රැෆික් නිර්මාණයේදී (Graphic Design) 'ටයිපොග්‍රැෆි' (Typography) යන පදයෙන් හඳුන්වන්නේ කුමක්ද?", "කලාත්මකව හා පැහැදිලිව අකුරු හැඩගැන්වීම හා සැකසීම", "තෙත් මැටි පතුරු කපා බඳුන් හා මූර්ති තැනීම", "කැටයම් කළ ලී කුට්ටි මගින් රෙදි මුද්‍රණය කිරීම", "ජ්‍යාමිතික රටා අනුව වීදුරු කැබලි ඇලවීම", "සිරස්තල, උප සිරස්තල හා අකුරු අතර ඉඩ නිවැරදිව සැකසීම පෝස්ටර් හා පොත් නිර්මාණයේ ප්‍රධාන අංගයකි."),
        q("අකුරු හැඩතල වර්ගීකරණයේදී 'සෙරිෆ්' (Serif) සහ 'සැන්ස්-සෙරිෆ්' (Sans-Serif) අකුරු වෙන් වන්නේ කෙසේද?", "සෙරිෆ් අකුරු කෙළවර කුඩා ඉරි ඇතත් සැන්ස්-සෙරිෆ්වල නැත", "සෙරිෆ් අකුරු සෑම විටම උණුසුම් රතු පැහැයෙන් පමණක් ලියයි", "සැන්ස්-සෙරිෆ් අකුරු සෑම විටම ඇල වූ අත් අකුරු හැඩ ගනී", "දෙකම සම්ප්‍රදායික පුස්කොළ පොත් සිංහල අක්ෂර ශෛලීන් වේ", "පොත් මුද්‍රණයට සෙරිෆ් ද, ඩිජිටල් තිර හා නූතන පෝස්ටර් සිරස්තලවලට සැන්ස්-සෙරිෆ් ද බහුලව ගනී."),
        q("පෝස්ටරයක හෝ දැන්වීමක 'දෘශ්‍ය ධුරාවලිය' (Visual Hierarchy) යනු කුමක්ද?", "වැදගත්ම තොරතුරට මුලින්ම ඇස යන සේ ප්‍රමාණය සැකසීම", "සියලුම සිරස්තල හා විස්තර එකම කුඩා ප්‍රමාණයෙන් ලිවීම", "ප්‍රධානම පණිවිඩය පෝස්ටරයේ පහළම කොනක කුඩාවට තැබීම", "පසුබිම හා අකුරු සඳහා එකම තානයේ වර්ණ දෙකක් භාවිත කිරීම", "වැදගත්ම දේ විශාලව හා තදින් තැබීමෙන් පණිවිඩය ක්ෂණිකව සන්නිවේදනය වේ."),
        q("වෙළඳපොළ හා පරිසර දැනුවත් කිරීම් සඳහා සිතුවම් ඇඳීමේදී 'ප්‍රචාරණ චිත්‍ර කලාව' (Commercial / Applied Art) සහ 'ලලිත කලාව' (Fine Art) වෙනස් වන්නේ කෙසේද?", "ව්‍යවහාරික කලාව සන්නිවේදනයටත් ලලිත කලාව රසවින්දනයටත් වේ", "ව්‍යවහාරික කලාව කළු-සුදු රේඛාවලට පමණක් සීමා වේ", "ලලිත කලාව පරිගණක මෘදුකාංගවලින් පමණක් නිර්මාණය කෙරේ", "ව්‍යවහාරික කලාව තුළ කිසිදු වර්ණ හෝ හැඩ මූලධර්මයක් නැත", "පෝස්ටර්, පොත් කවර, ඇසුරුම් හා ලාංඡන ව්‍යවහාරික කලාවටද, කැන්වස් චිත්‍ර හා ප්‍රතිමා ලලිත කලාවටද අයත් වේ."),
        q("ශ්‍රී ලංකාවේ හස්ත කර්මාන්ත අතර 'අම්බලන්ගොඩ' ප්‍රදේශය ලෝක ප්‍රසිද්ධ වී ඇත්තේ කුමන සාම්ප්‍රදායික කැටයම් හා වර්ණ කලාව නිසාද?", "කෝලම්, රක්ෂ, සන්නි වෙස්මුහුණු හා රූකඩ", "හපුවිද සම්ප්‍රදායික නියපොතු ලාක්ෂා කර්මාන්තය", "ඇම්බැක්කේ දේවාලයේ දැව පේකඩ හා කුළුණු කැටයම්", "පල්ලේබැද්ද හා මැදවල පාරම්පරික දුම්බර රටා පැදුරු", "සැහැල්ලු වෙල්කදුරු දැවයෙන් නෙළා දේශීය වර්ණවලින් සරසන ලද වෙස්මුහුණු අම්බලන්ගොඩ උරුමයකි."),
        q("වෙස්මුහුණු කැපීම සඳහා අම්බලන්ගොඩ ශිල්පීන් ප්‍රධාන වශයෙන් භාවිත කරන සැහැල්ලු හා කැටයමට පහසු දැව වර්ගය කුමක්ද?", "රුක් අත්තන හෝ වෙල්කදුරු (කදුරු ලී)", "කළුවර ලී", "යකඩ දැව", "ප්ලාස්ටික් පුවරු", "වෙල්කදුරු ලීය සැහැල්ලු වන අතර නැටුම් ශිල්පියාට පැළඳ සිටීමට පහසු මෙන්ම කැපීමටද සුදුසුය."),
        q("දේශීය කුඹල් කලාවේදී මැටි බඳුන් මත ඔපයක් හා තද කළු පැහැයක් ලබා ගැනීමට පැරණි ගැමි ශිල්පීන් කළේ කුමක්ද?", "උණු බඳුන් දහයියා තුළ දුම් ගැස්වීම හා ගලින් මැදීම", "පිළිස්සූ බඳුන් මත තෙල් සායම් හා වාර්නිෂ් තවරා වේළීම", "අමු මැටි බඳුන් සීතල ජලයේ පොඟවා අව්වේ තැබීම", "පිළිස්සීමට පෙර බඳුන් මත මී ඉටි හා ලාක්ෂා ආලේප කිරීම", "අවම ඔක්සිජන් දුම් ගැස්වීමෙන් හා ගුරු මැටි මැදීමෙන් (Burnishing) අලංකාර දිලිසෙන කළු හා රතු බඳුන් ලැබේ."),
        q("වස්ත්‍ර අලංකරණයේදී 'ස්වභාවික ඩයි' (Natural Dyes) ලබා ගැනීම සඳහා දේශීයව යොදාගත හැකි ශාක ද්‍රව්‍ය මොනවාද?", "කහ, කොස් ලී කුඩු, නිල් අවරිය හා රත්මල්", "කෘත්‍රිම ඇක්‍රිලික් වර්ණක හා ටර්පන්ටයින් ද්‍රාවණය", "සිමෙන්ති, හුණු සහ සියුම් කළුගල් කුඩු මිශ්‍රණය", "ප්ලාස්ටික් ඩයි හා පෙට්‍රෝලියම් රසායනික තෙල් වර්ග", "කෘත්‍රිම රසායනික ඩයි වර්ගවලට වඩා පරිසර හිතකාමී මෘදු වර්ණ ස්වභාවික ශාකවලින් ලබා ගත හැකිය."),
        q("පේෂකර්ම හා බතික් කලාවේදී 'නූල් කැරලි ඉටි රටා' නොමැතිව රෙද්දක කැටයම් කළ ලී අච්චුවකින් තීන්ත තබා මුද්‍රණය කිරීම කුමක්ද?", "ලී අච්චු මුද්‍රණය (Block Printing)", "චැන්ටිං බතික්", "කොයිලිං ක්‍රමය", "ටයි-ඩයි", "ඉන්දියාවේ හා ලංකාවේ බහුලව යොදන බ්ලොක් ප්‍රින්ටිං මගින් රෙදි මත ක්‍රමවත් මෝස්තර ඉක්මනින් මුද්‍රණය කරයි."),
        q("මූර්ති කලාවේ 'අර්ධ උන්නත කැටයම' (Low/Bas-Relief) සහ 'පූර්ණ වටකුරු මූර්තිය' (Sculpture in the Round) වෙනස් වන්නේ කෙසේද?", "අර්ධ උන්නත ඉදිරියෙන්ද වටකුරු සිව්පැත්තෙන්ද පෙනේ", "වටකුරු මූර්තිය යනු කඩදාසි මත ඇඳි ද්විමාන චිත්‍රයකි", "අර්ධ උන්නත කැටයම පිළිස්සූ මැටි බඳුන් පමණක් වේ", "දෙකම සැමවිටම බිත්ති බදාම මත ඇඳි සිතුවම් වර්ග වේ", "ඉසුරුමුණි පෙම් යුවළ අර්ධ උන්නත කැටයමකටත්, සමාධි පිළිමය පූර්ණ වටකුරු මූර්තියකටත් උදාහරණ වේ."),
        q("ගෘහ නිර්මාණ සැලසුමක 'පරිසර හිතකාමී හරිත වාස්තු කලාව' (Sustainable / Eco-Friendly Architecture) තුළ සැලකිලිමත් වන්නේ කුමක් කෙරෙහිද?", "ස්වභාවික වාතාශ්‍රය, හිරු එළිය, දේශීය අමුද්‍රව්‍ය හා ශක්තිය ඉතිරි කිරීම", "කෘත්‍රිම වායුසමීකරණ සහ සම්පූර්ණ වීදුරු බිත්ති", "ගස් කපා කොන්ක්‍රීට් දැමීම", "රසායනික ප්ලාස්ටික් භාවිතය", "ලංකාවේ පැරණි වරිච්චි නිවාස හා ජෙෆ්රි බාවාගේ නිර්මාණ ස්වභාවික සුළඟ හා ආලෝකය මනාව භාවිත කළේය."),
        q("කලා කෘතියක් ප්‍රදර්ශන පුවරුවක 'මවුන්ට් කිරීමේදී' (Mounting Artwork) අනුගමනය කරන නිවැරදි ප්‍රමිතිය කුමක්ද?", "පහළ දාරය මඳක් පළලින් වැඩිව සමබරව තැබීම", "චිත්‍රයේ මුල් මායිම් හතරම කතුරෙන් කපා දැමීම", "පසුබිමට ඉතා දීප්තිමත් රතු හෝ කහ පත්‍ර ඇලවීම", "සිතුවම පුවරුව මත විකර්ණ ලෙස ඇදට ඇලවීම", "පහළ දාරය මදක් පළලින් වැඩි වූ විට චිත්‍රය රාමුවෙන් ලිස්සා නොයන ස්ථාවර පෙනුමක් ඇසට ලැබේ."),
        q("අන්තර්ජාලය හා පරිගණක මෘදුකාංග යොදාගෙන නිර්මාණය කරන 'වෙක්ටර් ග්‍රැෆික්ස්' (Vector Graphics) හා 'රාස්ටර් රූප' (Raster Images) අතර වෙනස කුමක්ද?", "වෙක්ටර් රේඛාවලින්ද රාස්ටර් පික්සල්වලින්ද සෑදේ", "වෙක්ටර් රූප විශාල කළ විට පැහැදිලිව කැඩී බොඳ වේ", "රාස්ටර් රූප ගණිතමය වක්‍ර රේඛාවලින් පමණක් සෑදේ", "දෙකම පැරණි ලී අච්චු මුද්‍රණ ක්‍රම දෙකක් පමණි", "ලාංඡන (Logos) නිර්මාණයේදී ඕනෑම ප්‍රමාණයකට විශාල කළ හැකි බැවින් Vector ආකෘතිය යොදා ගනී."),
        q("වීදුරු හෝ පිඟන් කර්මාන්තයේදී 'ප්ලාස්ටර් ඔෆ් පැරිස්' (Plaster of Paris) බහුලව භාවිත කරන්නේ කුමන කාර්යය සඳහාද?", "මූර්ති අච්චු (Moulds) තැනීම හා වාත්තු කිරීම", "ජල සායම් සිතුවම් කඩදාසි මැද සිනිඳු කිරීම", "සාම්ප්‍රදායික බතික් රෙදි වර්ණවත් ඩයි කිරීම", "ග්‍රැෆයිට් චිත්‍ර පැන්සල් කූරු නිෂ්පාදනය කිරීම", "ජලය මිශ්‍ර කළ පසු ඉක්මනින් සවි වී සියුම් විස්තර ග්‍රහණය කරන නිසා අච්චු කර්මාන්තයට ඉතා සුදුසුය."),
        q("කලා නිර්මාණයක් විචාරය කිරීමේදී 'සාංදෘෂ්ටික හෙවත් යථාර්ථවාදී' (Representational) සහ 'වියුක්ත' (Non-Representational / Abstract) කෘති සංසන්දනය කරන්නේ කෙසේද?", "යථාර්ථවාදී කලාව ලෝකයද වියුක්ත කලාව හැඩ වර්ණද පෙන්වයි", "වියුක්ත කලාව සෑම විටම ශිල්පීය දුර්වලතාවක් පෙන්වයි", "යථාර්ථවාදී කලාවේදී කිසිදු වර්ණ හෝ තාන වෙනසක් නැත", "දෙකම ඡායාරූප ශිල්පයෙන් පමණක් බිහි වූ කලා අංග වේ", "කෘතියක් විනිශ්චය කිරීමට පෙර කලාකරුවා තෝරාගත් ශෛලිය හා අරමුණ හඳුනා ගැනීම විචාරකයාගේ යුතුකමයි."),
        q("විචාරකයෙකු 'සීගිරි බිතුසිතුවම්' විශ්ලේෂණය කරන විට පළමුව අවධානය යොමු කළ යුතු තාක්ෂණික කරුණක් කුමක්ද?", "රේඛා ලාලිත්‍යය හා ගුරුගල්-කහ ෆ්‍රෙස්කෝ වර්ණ", "යුරෝපීය කියුබිසම් හා ඩඩා කලා සම්ප්‍රදායේ ආභාසය", "හණ තෙල් මිශ්‍ර නූතන තෙල් සායම් තීන්ත භාවිතය", "ලෝහ තහඩු මත ඇසිඩ් යොදා කළ එචිං මුද්‍රණ තාක්ෂණය", "සෑම කලා කෘතියක්ම එය බිහි වූ යුගයේ මාධ්‍යය හා තාක්ෂණය අනුව විග්‍රහ කළ යුතුය."),
        q("විචාරයේදී 'ප්‍රකාශනවාදී' (Expressive) කලා කෘතියක ගුණාත්මකභාවය මනින ප්‍රධාන නිර්ණායකය කුමක්ද?", "නරඹන්නා තුළ මානසික හැඟීම් ප්‍රබලව ජනිත කිරීම", "කෘතිය ඡායාරූපයකට සියයට සියයක් සමාන වී තිබීම", "පින්සල් පහර කිසිවක් නොපෙනෙන සේ සිනිඳුව තිබීම", "සෑම රේඛාවක්ම කෝදුවෙන් නිවැරදිව මැන ඇඳ තිබීම", "උදාහරණයක් ලෙස මන්ච්ගේ 'විලාපය' හෝ ජස්ටින් දැරණියගලගේ කෘති ඇගයෙන්නේ හැඟීම් ප්‍රකාශන ශක්තියෙනි."),
        q("විචාරයේදී 'ආකෘතිවාදී' (Formalism) ප්‍රවේශය මගින් කලා කෘතියක් අගය කරන විට වැඩිම බරක් දෙන්නේ කුමකටද?", "වර්ණ, රේඛා, හැඩතල හා සංයුතියේ සංවිධානාත්මක බවට", "කලාකරුවාගේ පෞද්ගලික ජීවිත කතාව හා දේශපාලන මතයට", "සිතුවම් කැන්වසයේ භෞතික බර හා පළල ප්‍රමාණයට", "චිත්‍රයේ වෙළඳපොළ අලෙවි වටිනාකමට හා රාමු අලංකාරයට", "කලා මූලිකාංග හා මූලධර්ම මැනවින් සංවිධානය වී ඇති ආකාරය Formalism හිදී ප්‍රධාන වේ."),
        q("කලා නිර්මාණයේදී 'ස්කෙච්බුක්' (Sketchbook / සටහන් පොත) භාවිතය ශිෂ්‍යයෙකුට අතිශය වැදගත් වන්නේ ඇයි?", "නිරීක්ෂණ, අදහස් හා ඉක්මන් ඉරියව් සටහන් කිරීමට", "අන් අයගේ ප්‍රකාශිත කෘති වෙනසකින් තොරව කොපි කිරීමට", "ගණිත සමීකරණ හා විද්‍යා ප්‍රස්තාර පමණක් ලියා තැබීමට", "විභාග ශාලාව තුළට පිළිතුරු සටහන් රැගෙන යාම සඳහා", "දිනපතා පරිසරයේ සත්ව, ශාක හා මිනිස් ඉරියව් සටහන් කිරීමෙන් දක්ෂ නිර්මාණ ශිල්පියෙකු බිහිවේ."),
        q("කලා නිර්මාණ සඳහා අන්තර්ජාලයෙන් හෝ වෙනත් කලාකරුවෙකුගෙන් කෘතියක් 'හරියටම කොපි කිරීම' (Plagiarism) සදාචාරාත්මක නොවන්නේ ඇයි?", "ස්වීයත්වය නැති වී බුද්ධිමය දේපළ අයිතිය බිඳෙන බැවින්", "කොපි කිරීම නිසා ප්‍රායෝගික විභාගයෙන් අමතර ලකුණු ලැබෙන බැවින්", "කෘතියේ මුල් වර්ණ චක්‍රය සම්පූර්ණයෙන් වෙනස් වන බැවින්", "මූලික රේඛීය දෘෂ්ටිකෝණ නීති ස්වයංක්‍රීයව බිඳ වැටෙන බැවින්", "පැරණි කෘතිවලින් ආභාසය ලබා ගැනීම හොඳ වුවද, අවසන් නිර්මාණය තමන්ගේම අව්‍යාජ අදහසක් විය යුතුය."),
        q("සම්ප්‍රදායික ශ්‍රී ලාංකේය බිතුසිතුවම් සංරක්ෂණයේදී 'අමතර ආර්ද්‍රතාව' (තෙතමනය) හා 'වවුලන්/කෘමීන්' පාලනය වැදගත් වන්නේ ඇයි?", "තෙතමනය නිසා හුණු බදාමය පිපිරී ලුණු බැඳී වර්ණ ස්තරය ගැලවී යන බැවින්", "වර්ණ තවත් දීප්තිමත් වන නිසා", "සිතුවම් ප්‍රමාණයෙන් විශාල වන නිසා", "බිත්ති රන් පැහැ ගැන්වෙන නිසා", "සීගිරි, දඹුලු හා තිවංක සිතුවම් රැක ගැනීමට වාතාශ්‍රය, ආලෝක මට්ටම හා ජල කාන්දු නිරන්තරයෙන් පාලනය කරයි."),
        q("ශ්‍රී ලංකාවේ දේශීය හා විදේශීය කලා නිර්මාණ අධ්‍යයනය කිරීමෙන් සාමාන්‍ය පෙළ සිසුවෙකු ලබන ප්‍රධාන පෞරුෂ වර්ධනය කුමක්ද?", "නිර්මාණශීලී චින්තනය, සංස්කෘතික අභිමානය හා විචාර බුද්ධිය", "කාර්මික යන්ත්‍ර සූත්‍ර නඩත්තුව හා විද්‍යුත් පරිපථ පාලනය", "තොරතුරු අර්ථ නොදැන කටපාඩම් කර ඉක්මනින් අමතක කිරීම", "මිල අධික ආනයනික භාණ්ඩ වෙළඳපොළෙන් තෝරා ගැනීම", "කලාව යනු අපගේ සංස්කෘතික උරුමය රැකගනිමින් ලෝකය සුන්දරව හා විචාරශීලීව දැකීමට උගන්වන විෂයකි."),
        q("රේඛීය දෘෂ්ටිකෝණයේදී 'දෙපැත්තේ පිහිටි ගස් පේළියක් හෝ විදුලි කණු පේළියක්' ඈතට ඇඳීමේදී ඒවා අතර පරතරය වෙනස් වන්නේ කෙසේද?", "අභිසාරී ලක්ෂ්‍යයට ළං වෙත්ම උස මෙන්ම පරතරයද කුඩා වේ", "ගස්වල උස අඩු වුවත් පරතරය සමානවම නොවෙනස්ව පවතී", "අභිසාරී ලක්ෂ්‍යයට ළං වන විට ගස් ප්‍රමාණයෙන් විශාල වේ", "ගස් අතර පරතරය ඈතට යාමේදී ක්‍රමයෙන් දෙගුණ වී පළල් වේ", "දෘෂ්ටිකෝණ නියමය අනුව දුර වැඩි වන විට වස්තුවේ ප්‍රමාණයත් පරතරයත් යන දෙකම ක්‍රමයෙන් හැකිළී පෙනේ."),
        q("චිත්‍ර කලා කෘතියක් ප්‍රදර්ශනය කරන කෞතුකාගාරයක (Art Museum / Gallery) සංචාරකයන්ට ෆ්ලෑෂ් ආලෝකය (Flash Photography) භාවිතය තහනම් කරන්නේ ඇයි?", "තීව්‍ර ආලෝක කිරණ නිසා පැරණි ස්වභාවික වර්ණ මැකෙන බැවින්", "නරඹන්නන්ගේ කැමරා උපකරණවල බැටරි ආයුෂ ඉතිරි කිරීම සඳහා", "ඡායාරූප ගැනීමේදී සිතුවම් රාමු බිත්තියෙන් ගැලවී වැටෙන නිසා", "කෞතුකාගාර ශාලාවේ විදුලි පරිභෝජනය හා වියදම අඩු කිරීම සඳහා", "සීගිරිය හා ලූවර් වැනි ලෝක උරුම කලාගාරවල ආලෝක සංවේදී වර්ණක ආරක්ෂා කිරීමට මෙම නීතිය පනවා ඇත.")
    )
}
